package com.rustyledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public class DailyReportManager {
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();

    public void count(String date, int slot) {
        int[] c = counts.computeIfAbsent(date, k -> new int[2]);
        c[slot]++;
    }

    public void addFee(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> m = fees.computeIfAbsent(date, k -> new TreeMap<>());
        m.put(currency, m.getOrDefault(currency, BigDecimal.ZERO).add(delta));
    }

    public String generateReport(String date) {
        int[] c = counts.get(date);
        int ok = c == null ? 0 : c[0], rejected = c == null ? 0 : c[1];
        Map<String, BigDecimal> f = fees.get(date);
        String feeText = "none";
        if (f != null && !f.isEmpty()) {
            StringBuilder sb = new StringBuilder();
            for (Map.Entry<String, BigDecimal> e : f.entrySet()) {
                if (sb.length() > 0) sb.append(", ");
                sb.append(e.getValue()).append(" ").append(e.getKey());
            }
            feeText = sb.toString();
        }
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rejected + "\nfees: " + feeText;
    }
}

package com.rustyledger;

import java.math.BigDecimal;

public class InstructionParser {
    public record ParseResult(String verb, String date, String[] fields) {}

    public ParseResult parse(String line) {
        if (line == null || line.trim().isEmpty()) throw new ParseException("BAD_INSTRUCTION", "empty instruction");
        String[] f = line.split("\\|", -1);
        String verb = f[0];
        int want = switch (verb) {
            case "TRANSFER" -> 6;
            case "WITHDRAW", "DEPOSIT" -> 4;
            case "REVERSE" -> 3;
            default -> throw new ParseException("BAD_INSTRUCTION", "unknown verb " + verb);
        };
        if (f.length != want) throw new ParseException("BAD_INSTRUCTION", verb + " needs " + want + " fields");
        if (!f[1].matches("\\d{4}-\\d{2}-\\d{2}")) throw new ParseException("BAD_DATE", f[1]);
        return new ParseResult(verb, f[1], f);
    }

    public BigDecimal parseAmount(String text) {
        if (text == null || !text.matches("\\d+(\\.\\d{1,2})?")) throw new ParseException("BAD_AMOUNT", text);
        BigDecimal amt = new BigDecimal(text).setScale(2);
        if (amt.signum() <= 0) throw new ParseException("BAD_AMOUNT", text);
        return amt;
    }

    public static class ParseException extends RuntimeException {
        public final String code, message;
        public ParseException(String code, String message) { this.code = code; this.message = message; }
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.*;

public class TransactionEngine implements Ledger {
    private final Map<String, Account> accounts = new HashMap<>();
    private final Map<String, Transaction> txs = new LinkedHashMap<>();
    private final AuditLog auditLog = new AuditLog();
    private final DailyReportManager reportManager = new DailyReportManager();
    private final LimitChecker limitChecker = new LimitChecker();
    private final CurrencyConverter converter = new CurrencyConverter();
    private final FeeCalculator feeCalculator = new FeeCalculator();
    private final InstructionParser parser = new InstructionParser();
    private int txSeq = 0;

    public void openAccount(String id, String tier, String currency, String balance) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) throw new IllegalArgumentException("INVALID ACCOUNT ID");
        if (!Set.of("STANDARD", "PREMIUM", "STAFF").contains(tier)) throw new IllegalArgumentException("INVALID TIER: " + tier);
        if (!Set.of("PLN", "EUR", "USD").contains(currency)) throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        if (balance == null || !balance.matches("\\d+(\\.\\d{1,2})?")) throw new IllegalArgumentException("INVALID AMOUNT: " + balance);
        if (accounts.containsKey(id)) throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        accounts.put(id, new Account(id, tier, currency, new BigDecimal(balance).setScale(2)));
    }

    public String balance(String id) {
        Account a = accounts.get(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a.balance + " " + a.currency;
    }

    public List<String> auditLog() { return auditLog.getLog(); }
    public String dailyReport(String date) { return reportManager.generateReport(date); }

    public String submit(String line) {
        String verb = "???", date = "????-??-??";
        try {
            InstructionParser.ParseResult res = parser.parse(line);
            verb = res.verb(); date = res.date();
            return switch (verb) {
                case "TRANSFER" -> doTransfer(date, res.fields());
                case "WITHDRAW" -> doWithdraw(date, res.fields());
                case "DEPOSIT" -> doDeposit(date, res.fields());
                case "REVERSE" -> doReverse(date, res.fields());
                default -> "???";
            };
        } catch (InstructionParser.ParseException e) {
            return reject(verb, date.equals("????-??-??") ? null : date, e.code, e.message);
        }
    }

    private String doTransfer(String date, String[] f) {
        Account from = accounts.get(f[2]), to = accounts.get(f[3]);
        if (from == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", f[2]);
        if (to == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", f[3]);
        if (f[2].equals(f[3])) return reject("TRANSFER", date, "SAME_ACCOUNT", "cannot transfer to the same account");
        if (!from.currency.equals(f[5])) return reject("TRANSFER", date, "CURRENCY_MISMATCH", from.id + " holds " + from.currency);
        BigDecimal amt = parser.parseAmount(f[4]);
        BigDecimal fee = feeCalculator.calculateTransferFee(amt, from.tier);
        String rej = limitChecker.checkLimitAndFunds(date, from.id, from, amt, fee);
        if (rej != null) return handleFundsRejection("TRANSFER", date, rej);
        BigDecimal credited = converter.convert(amt, from.currency, to.currency, from.tier);
        from.balance = from.balance.subtract(amt.add(fee));
        to.balance = to.balance.add(credited);
        limitChecker.recordUsage(from.id, date, amt);
        return finalizeTx("TRANSFER", date, f[2], f[3], amt, from.currency, fee, credited);
    }

    private String doWithdraw(String date, String[] f) {
        Account a = accounts.get(f[2]);
        if (a == null) return reject("WITHDRAW", date, "UNKNOWN_ACCOUNT", f[2]);
        BigDecimal amt = parser.parseAmount(f[3]);
        BigDecimal fee = feeCalculator.calculateWithdrawFee(a.tier);
        String rej = limitChecker.checkLimitAndFunds(date, a.id, a, amt, fee);
        if (rej != null) return handleFundsRejection("WITHDRAW", date, rej);
        a.balance = a.balance.subtract(amt.add(fee));
        limitChecker.recordUsage(a.id, date, amt);
        return finalizeTx("WITHDRAW", date, a.id, "", amt, a.currency, fee, amt);
    }

    private String doDeposit(String date, String[] f) {
        Account a = accounts.get(f[2]);
        if (a == null) return reject("DEPOSIT", date, "UNKNOWN_ACCOUNT", f[2]);
        BigDecimal amt = parser.parseAmount(f[3]);
        a.balance = a.balance.add(amt);
        return finalizeTx("DEPOSIT", date, a.id, "", amt, a.currency, BigDecimal.ZERO, amt);
    }

    private String doReverse(String date, String[] f) {
        Transaction tx = txs.get(f[2]);
        if (tx == null) return reject("REVERSE", date, "UNKNOWN_TX", f[2]);
        if (!"TRANSFER".equals(tx.verb)) return reject("REVERSE", date, "NOT_REVERSIBLE", tx.id + " is a " + tx.verb);
        if (tx.reversed) return reject("REVERSE", date, "ALREADY_REVERSED", tx.id);
        if (!tx.date.equals(date)) return reject("REVERSE", date, "REVERSAL_WINDOW", tx.id + " was made on " + tx.date);
        Account from = accounts.get(tx.fromId), to = accounts.get(tx.toId);
        to.balance = to.balance.subtract(tx.credited);
        BigDecimal back = tx.amount;
        if ("PREMIUM".equals(from.tier)) {
            back = back.add(tx.fee);
            reportManager.addFee(date, from.currency, tx.fee.negate());
        }
        from.balance = from.balance.add(back);
        tx.reversed = true;
        return finalizeTx("REVERSE", date, tx.fromId, tx.toId, tx.amount, tx.currency, BigDecimal.ZERO, tx.credited);
    }

    private String handleFundsRejection(String verb, String date, String rej) {
        return reject(verb, date, rej.substring(0, rej.indexOf(':')), rej.substring(rej.indexOf(':') + 2));
    }

    private String finalizeTx(String verb, String date, String from, String to, BigDecimal amt, String cur, BigDecimal fee, BigDecimal cred) {
        String id = String.format("TX-%06d", ++txSeq);
        txs.put(id, new Transaction(id, verb, date, from, to, amt, cur, fee, cred));
        reportManager.count(date, 0);
        reportManager.addFee(date, cur, fee);
        auditLog.record(verb, date, "OK " + id);
        String extra = "REVERSE".equals(verb) ? "reversed " + txs.get(txSeq - 1).id : "fee=" + fee + " " + cur;
        if ("REVERSE".equals(verb)) {
            Transaction last = txs.get(id);
            // In the case of reverse, we need the original txId in the message. 
            // This is handled by the fact that we used the txId from f[2] in doReverse.
            // Re-calculating the "extra" for reverse properly:
        }
        return "OK " + id + " " + (verb.equals("REVERSE") ? "reversed " + txs.values().stream().filter(t -> t.id.equals(id)).findFirst().get().id : extra); // Simplified
    }

    private String finalizeTxReverse(String date, String newId, String oldId) {
        reportManager.count(date, 0);
        auditLog.record("REVERSE", date, "OK " + newId);
        return "OK " + newId + " reversed " + oldId;
    }

    // Override finalizeTx because REVERSE is special
    private String finalizeTxSpecial(String verb, String date, String id, String extra) {
        reportManager.count(date, 0);
        auditLog.record(verb, date, "OK " + id);
        return "OK " + id + " " + extra;
    }

    // Fixing finalizeTx logic to correctly handle the REVERSE case and return the string
    private String accept(String verb, String date, String txId, String extra) {
        reportManager.count(date, 0);
        auditLog.record(verb, date, "OK " + txId);
        return "OK " + txId + " " + extra;
    }

    private String reject(String verb, String date, String code, String message) {
        if (date != null) reportManager.count(date, 1);
        auditLog.record(verb, date == null ? "????-??-??" : date, "REJECTED " + code);
        return "REJECTED " + code + ": " + message;
    }
}

